using System.Text;
using Microsoft.AspNetCore.Html;
using Microsoft.AspNetCore.Mvc.Rendering;

namespace VIUUniversity.Html;

/// <summary>
/// Renders responsive images that prefer the WebP twins generated by the image pipeline.
///
/// The pipeline writes, next to every raster image:
///     &lt;name&gt;.webp      (largest variant, max 1600px)
///     &lt;name&gt;@sm.webp   (640px, for phones)
///
/// The original .jpg/.png is kept untouched as the fallback source, so browsers without
/// WebP and crawlers still render normally.
///
/// This is an IHtmlHelper extension rather than a tag helper on purpose: views in this
/// project are compiled into the same assembly, and Razor's "@addTagHelper *, SameAssembly"
/// discovery does not see tag helpers defined there.
/// </summary>
public static class MediaExtensions
{
    private const string Root = "/images/";
    private const int LargeWidth = 1600;
    private const int SmallWidth = 640;

    /// <summary>
    /// Emits a <c>&lt;picture&gt;</c> + <c>&lt;img&gt;</c> pair.
    /// </summary>
    /// <param name="html">The helper this method extends.</param>
    /// <param name="src">Image path, normally a site-relative URL from the database.</param>
    /// <param name="alt">
    /// Alternative text. Pass <see cref="string.Empty"/> for a purely decorative image —
    /// an empty alt is what makes screen readers skip it instead of reading the filename.
    /// </param>
    /// <param name="class">Optional CSS classes for the img element.</param>
    /// <param name="style">Optional inline style for the img element.</param>
    /// <param name="sizes">
    /// Width hint for the browser's srcset selection, e.g. "(max-width: 768px) 100vw, 33vw".
    /// Getting this roughly right is what stops phones from downloading desktop-sized files.
    /// </param>
    /// <param name="eager">
    /// True for above-the-fold images (hero, first row of cards): skips lazy loading and
    /// raises fetch priority. Use sparingly — marking everything eager hurts LCP.
    /// </param>
    /// <param name="fallback">
    /// Used when <paramref name="src"/> is blank, so a record without an image still
    /// renders a tile instead of a broken-image icon.
    /// </param>
    public static IHtmlContent Img(
        this IHtmlHelper html,
        string? src,
        string? alt = "",
        string? @class = null,
        string? style = null,
        string? sizes = null,
        bool eager = false,
        string fallback = "/images/news-placeholder.jpg")
    {
        if (string.IsNullOrWhiteSpace(src))
        {
            src = fallback;
        }

        var url = html.ViewContext.HttpContext.RequestServices
            .GetRequiredService<IWebHostEnvironment>();

        var builder = new StringBuilder(320);

        if (TryGetVariants(url, src!, out var large, out var small))
        {
            builder.Append("<picture>")
                   .Append("<source type=\"image/webp\" sizes=\"")
                   .Append(Attr(sizes ?? "100vw"))
                   .Append("\" srcset=\"")
                   .Append(small).Append(' ').Append(SmallWidth).Append("w, ")
                   .Append(large).Append(' ').Append(LargeWidth)
                   .Append("w\">");
        }

        builder.Append("<img src=\"").Append(Attr(src!)).Append('"')
               .Append(" alt=\"").Append(Attr(alt ?? string.Empty)).Append('"');

        if (!string.IsNullOrWhiteSpace(@class))
        {
            builder.Append(" class=\"").Append(Attr(@class)).Append('"');
        }

        if (!string.IsNullOrWhiteSpace(style))
        {
            builder.Append(" style=\"").Append(Attr(style)).Append('"');
        }

        if (eager)
        {
            builder.Append(" fetchpriority=\"high\" decoding=\"async\"");
        }
        else
        {
            builder.Append(" loading=\"lazy\" decoding=\"async\"");
        }

        builder.Append('>');

        if (large.Length > 0)
        {
            builder.Append("</picture>");
        }

        return new HtmlString(builder.ToString());
    }

    /// <summary>
    /// Maps an image URL onto its WebP twins, or returns false when there is no local
    /// WebP twin (remote URL, placeholder, missing file) so callers emit a plain img.
    /// </summary>
    private static bool TryGetVariants(
        IWebHostEnvironment env, string src, out string large, out string small)
    {
        large = small = string.Empty;

        if (!src.StartsWith(Root, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var query = string.Empty;
        var queryIndex = src.IndexOf('?');
        if (queryIndex >= 0)
        {
            query = src[queryIndex..];
            src = src[..queryIndex];
        }

        var extension = Path.GetExtension(src).ToLowerInvariant();
        if (extension is not (".jpg" or ".jpeg" or ".png"))
        {
            return false;
        }

        var stem = src[..^extension.Length];

        // The variant lives at <webroot><stem>.webp. Probing the filesystem on every render
        // is cheap (one stat call) and avoids maintaining a manifest that would drift out
        // of sync the first time an editor uploads a new image.
        var disk = Path.Combine(env.WebRootPath ?? string.Empty,
            stem.TrimStart('/').Replace('/', Path.DirectorySeparatorChar));

        if (!File.Exists(disk + ".webp"))
        {
            return false;
        }

        large = stem + ".webp" + query;
        small = stem + "@sm.webp" + query;
        return true;
    }

    /// <summary>
    /// Escapes only the four characters that are unsafe inside a double-quoted
    /// attribute value. Unlike <c>HtmlEncoder.Default</c> this leaves Vietnamese
    /// diacritics as literal UTF-8 instead of emitting "To&#xE0; nh&#xE0;" — which
    /// renders identically but bloats the HTML and hurts readability in view source.
    /// </summary>
    private static string Attr(string value)
    {
        if (string.IsNullOrEmpty(value))
        {
            return string.Empty;
        }

        var needsEscaping = false;
        foreach (var c in value)
        {
            if (c is '&' or '<' or '>' or '"')
            {
                needsEscaping = true;
                break;
            }
        }

        if (!needsEscaping)
        {
            return value;
        }

        var builder = new StringBuilder(value.Length + 16);
        foreach (var c in value)
        {
            builder.Append(c switch
            {
                '&' => "&amp;",
                '<' => "&lt;",
                '>' => "&gt;",
                '"' => "&quot;",
                _ => c.ToString(),
            });
        }

        return builder.ToString();
    }
}